export interface PaginationResult<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

export function getPaginationParams(query: any): {
  page: number;
  limit: number;
  offset: number;
} {
  const page = Math.max(1, parseInt(query.page || '1', 10));
  const limit = Math.max(1, Math.min(100, parseInt(query.limit || '10', 10)));
  const offset = (page - 1) * limit;
  return { page, limit, offset };
}

export function createPaginationResult<T>(
  data: T[],
  total: number,
  page: number,
  limit: number,
): PaginationResult<T> {
  return {
    data,
    meta: {
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    },
  };
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Reflector } from '@nestjs/core';
import { WriteAuditLogUseCase } from '../../modules/audit/application/usecases/write-audit-log.usecase';

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  constructor(
    private readonly reflector: Reflector,
    private readonly writeAuditLogUseCase: WriteAuditLogUseCase,
  ) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const req = context.switchToHttp().getRequest();
    const user = req.user;
    const method = req.method;
    const url = req.url;

    // Skip GET requests or if no user (public endpoints)
    if (method === 'GET' || !user) {
      return next.handle();
    }

    const ip = req.ip || req.connection.remoteAddress;
    const userAgent = req.headers['user-agent'];
    const resource =
      this.reflector.get<string>('resource', context.getHandler()) ||
      url.split('/')[1] ||
      'UNKNOWN';
    const action = `${method} ${url}`;

    return next.handle().pipe(
      tap(async (data) => {
        // Log successful modification
        // If it's a POST/PUT/PATCH/DELETE
        try {
          await this.writeAuditLogUseCase.execute({
            userId: user.userId,
            action: method,
            resource: resource,
            resourceId: req.params.id || (data && data.id) || null,
            ipAddress: ip,
            userAgent: userAgent,
            // We could log oldData/newData if we intercept properly, but for now log basic action
            newData: method !== 'DELETE' ? data : null,
          });
        } catch (error) {
          console.error('Audit Log Error:', error);
          // Don't fail the request if audit logging fails
        }
      }),
    );
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface Response<T> {
  success: boolean;
  statusCode: number;
  data: T;
  timestamp: string;
  path: string;
  requestId: string;
}

@Injectable()
export class ResponseInterceptor<T> implements NestInterceptor<T, Response<T>> {
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<Response<T>> {
    const ctx = context.switchToHttp();
    const response = ctx.getResponse();
    const request = ctx.getRequest();
    const statusCode = response.statusCode;

    return next.handle().pipe(
      map((data) => ({
        success: true,
        statusCode,
        data,
        timestamp: new Date().toISOString(),
        path: request.url,
        requestId: request.headers['x-request-id'],
      })),
    );
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  RequestTimeoutException,
} from '@nestjs/common';
import { Observable, throwError, TimeoutError } from 'rxjs';
import { catchError, timeout } from 'rxjs/operators';

@Injectable()
export class TimeoutInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    return next.handle().pipe(
      timeout(5000),
      catchError((err) => {
        if (err instanceof TimeoutError) {
          return throwError(() => new RequestTimeoutException());
        }
        return throwError(() => err);
      }),
    );
  }
}

import { Injectable, Logger, NestMiddleware } from '@nestjs/common';
import { NextFunction, Request, Response } from 'express';

@Injectable()
export class LoggerMiddleware implements NestMiddleware {
  private logger = new Logger('HTTP');

  use(req: Request, res: Response, next: NextFunction): void {
    const { ip, method, baseUrl } = req;
    const userAgent = req.get('user-agent') || '';
    const start = Date.now();

    res.on('finish', () => {
      const { statusCode } = res;
      const duration = Date.now() - start;
      const requestId = req.headers['x-request-id'];

      const message = `${method} ${baseUrl} ${statusCode} ${duration}ms - ${userAgent} ${ip} [${requestId}]`;

      if (process.env.NODE_ENV === 'production') {
        this.logger.log(
          JSON.stringify({
            method,
            url: baseUrl,
            statusCode,
            duration,
            userAgent,
            ip,
            requestId,
          }),
        );
      } else {
        this.logger.log(message);
      }
    });

    next();
  }
}

export class SanitizeUtil {
  static trim(obj: any): any {
    if (typeof obj === 'string') {
      return obj.trim();
    }
    if (typeof obj !== 'object' || obj === null) {
      return obj;
    }
    if (Array.isArray(obj)) {
      return obj.map((item) => SanitizeUtil.trim(item));
    }
    return Object.keys(obj).reduce((acc, key) => {
      acc[key] = SanitizeUtil.trim(obj[key]);
      return acc;
    }, {} as any);
  }
}

import {
  BadRequestException,
  ConflictException,
  InternalServerErrorException,
  UnprocessableEntityException,
} from '@nestjs/common';

export class PgErrorMapper {
  static map(error: any): void {
    if (!error.code) {
      throw error;
    }

    switch (error.code) {
      case '23505': // unique_violation
        throw new ConflictException('Resource already exists');
      case '23503': // foreign_key_violation
        throw new UnprocessableEntityException('Referenced resource not found');
      case '23502': // not_null_violation
        throw new BadRequestException('Missing required fields');
      case '23514': // check_violation
        throw new UnprocessableEntityException('Validation check failed');
      case '57014': // query_canceled
        throw new InternalServerErrorException('Query timeout');
      default:
        throw error;
    }
  }
}

