import {
  Inject,
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Pool } from 'pg';
import databaseConfig from '../config/database.config';

@Injectable()
export class DatabasePool implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(DatabasePool.name);
  private pool: Pool;

  constructor(
    @Inject(databaseConfig.KEY)
    private readonly dbConfig: ConfigType<typeof databaseConfig>,
  ) {
    this.pool = new Pool({
      host: this.dbConfig.host,
      port: this.dbConfig.port,
      user: this.dbConfig.user,
      password: this.dbConfig.password,
      database: this.dbConfig.name,
      max: this.dbConfig.maxConnections,
      min: this.dbConfig.minConnections,
      ssl: this.dbConfig.ssl ? { rejectUnauthorized: false } : undefined,
    });
  }

  async onModuleInit() {
    try {
      const client = await this.pool.connect();
      this.logger.log('Database connection established successfully');
      client.release();
    } catch (error) {
      this.logger.error('Failed to connect to the database', error.stack);
      throw error;
    }
  }

  async onModuleDestroy() {
    await this.pool.end();
    this.logger.log('Database connection pool closed');
  }

  getPool(): Pool {
    return this.pool;
  }
}

import { DatabasePool } from '../pool';
import { Logger } from '@nestjs/common';

export abstract class BaseRepository<T> {
  protected readonly logger: Logger;

  constructor(
    protected readonly pool: DatabasePool,
    protected readonly tableName: string,
  ) {
    this.logger = new Logger(this.constructor.name);
  }

  protected async query<R = any>(text: string, params?: any[]): Promise<R[]> {
    const client = await this.pool.getPool().connect();
    try {
      const result = await client.query(text, params);
      return result.rows;
    } finally {
      client.release();
    }
  }

  protected async queryOne<R = any>(
    text: string,
    params?: any[],
  ): Promise<R | null> {
    const rows = await this.query<R>(text, params);
    return rows.length > 0 ? rows[0] : null;
  }

  async findAll(): Promise<T[]> {
    return this.query<T>(`SELECT * FROM ${this.tableName}`);
  }

  async findById(id: string): Promise<T | null> {
    return this.queryOne<T>(`SELECT * FROM ${this.tableName} WHERE id = $1`, [
      id,
    ]);
  }

  async delete(id: string): Promise<boolean> {
    const result = await this.query(
      `DELETE FROM ${this.tableName} WHERE id = $1 RETURNING id`,
      [id],
    );
    return result.length > 0;
  }
}

import { Pool } from 'pg';
import * as dotenv from 'dotenv';
import * as path from 'path';
import * as bcrypt from 'bcrypt';

dotenv.config({ path: path.resolve(__dirname, '../../.env') });

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT || '5432'),
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
});

async function main() {
  const client = await pool.connect();
  try {
    console.log('Seeding database with extended data (10+ items per table)...');
    await client.query('BEGIN');

    // Helpers
    const getRandomItem = <T>(arr: T[]): T =>
      arr[Math.floor(Math.random() * arr.length)];
    const getRandomInt = (min: number, max: number) =>
      Math.floor(Math.random() * (max - min + 1)) + min;

    // 1. Create Users (15 users)
    console.log('Creating users...');
    const passwordHash = await bcrypt.hash('password123', 10);
    const roles = ['ADMIN', 'MANAGER', 'MEMBER', 'MEMBER', 'MEMBER'];
    const userIds: string[] = [];

    // Always ensure specific test users exist
    const fixedUsers = [
      {
        email: 'admin@trivexa.com',
        role: 'ADMIN',
        first: 'Admin',
        last: 'User',
      },
      {
        email: 'manager@trivexa.com',
        role: 'MANAGER',
        first: 'John',
        last: 'Manager',
      },
      { email: 'dev@trivexa.com', role: 'MEMBER', first: 'Jane', last: 'Dev' },
    ];

    for (const u of fixedUsers) {
      const res = await client.query(
        `
                INSERT INTO users (email, password_hash, first_name, last_name, role, is_active)
                VALUES ($1, $2, $3, $4, $5, $6)
                ON CONFLICT (email) DO UPDATE SET email = EXCLUDED.email
                RETURNING id;
            `,
        [u.email, passwordHash, u.first, u.last, u.role, true],
      );
      userIds.push(res.rows[0].id);
    }

    // Generate random users
    for (let i = 1; i <= 12; i++) {
      const role = getRandomItem(roles);
      const res = await client.query(
        `
