import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { Client, ClientEntity } from '../domain/client.entity';

@Injectable()
export class ClientsRepository {
  constructor(private readonly dbPool: DatabasePool) {}

  async findAll(query: {
    page: number;
    limit: number;
    search?: string;
    isActive?: string;
  }): Promise<{ data: ClientEntity[]; total: number }> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = [];
      const params: any[] = [];
      let paramIndex = 1;

      if (query.isActive !== undefined) {
        conditions.push(`is_active = $${paramIndex++}`);
        params.push(query.isActive === 'true');
      }
      if (query.search) {
        conditions.push(
          `(LOWER(company_name) LIKE $${paramIndex} OR LOWER(contact_person) LIKE $${paramIndex} OR LOWER(email) LIKE $${paramIndex})`,
        );
        params.push(`%${query.search.toLowerCase()}%`);
        paramIndex++;
      }

      const whereClause = conditions.length
        ? `WHERE ${conditions.join(' AND ')}`
        : '';

      const countResult = await BaseQuery.queryOne<{ count: string }>(
        client,
        `SELECT COUNT(*) as count FROM clients ${whereClause}`,
        params,
      );
      const total = parseInt(countResult?.count || '0', 10);

      const offset = (query.page - 1) * query.limit;
      params.push(query.limit, offset);
      const rows = await BaseQuery.queryMany(
        client,
        `SELECT id, company_name, contact_person, email, phone, address, is_active, created_at, updated_at
                 FROM clients ${whereClause}
                 ORDER BY created_at DESC
                 LIMIT $${paramIndex++} OFFSET $${paramIndex++}`,
        params,
      );

      return {
        data: rows.map(Client.fromRow),
        total,
      };
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<ClientEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `SELECT id, company_name, contact_person, email, phone, address, is_active, created_at, updated_at
                 FROM clients WHERE id = $1`,
        [id],
      );
      return row ? Client.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findByEmail(email: string): Promise<ClientEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `SELECT id, company_name, contact_person, email, phone, address, is_active, created_at, updated_at
                 FROM clients WHERE email = $1`,
        [email],
      );
      return row ? Client.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findByCompanyName(name: string): Promise<ClientEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `SELECT id, company_name, contact_person, email, phone, address, is_active, created_at, updated_at
                 FROM clients WHERE company_name = $1`,
        [name],
      );
      return row ? Client.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async create(data: {
    companyName: string;
    contactPerson: string;
    email: string;
    phone?: string;
    address?: string;
  }): Promise<ClientEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `INSERT INTO clients (company_name, contact_person, email, phone, address)
                 VALUES ($1, $2, $3, $4, $5)
                 RETURNING id, company_name, contact_person, email, phone, address, is_active, created_at, updated_at`,
        [
          data.companyName,
          data.contactPerson,
          data.email,
          data.phone || null,
          data.address || null,
        ],
      );
      return Client.fromRow(row);
    } finally {
      client.release();
    }
  }

  async update(
    id: string,
    data: Partial<{
      companyName: string;
      contactPerson: string;
      email: string;
      phone: string;
      address: string;
    }>,
  ): Promise<ClientEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const setClauses: string[] = [];
      const params: any[] = [];
      let paramIndex = 1;

      if (data.companyName !== undefined) {
        setClauses.push(`company_name = $${paramIndex++}`);
        params.push(data.companyName);
      }
      if (data.contactPerson !== undefined) {
        setClauses.push(`contact_person = $${paramIndex++}`);
        params.push(data.contactPerson);
      }
      if (data.email !== undefined) {
        setClauses.push(`email = $${paramIndex++}`);
        params.push(data.email);
      }
      if (data.phone !== undefined) {
        setClauses.push(`phone = $${paramIndex++}`);
        params.push(data.phone);
      }
      if (data.address !== undefined) {
        setClauses.push(`address = $${paramIndex++}`);
        params.push(data.address);
      }

      if (setClauses.length === 0) return this.findById(id);

      setClauses.push(`updated_at = NOW()`);
      params.push(id);

      const row = await BaseQuery.queryOne(
        client,
        `UPDATE clients SET ${setClauses.join(', ')}
                 WHERE id = $${paramIndex}
                 RETURNING id, company_name, contact_person, email, phone, address, is_active, created_at, updated_at`,
        params,
      );
      return row ? Client.fromRow(row) : null;
    } finally {
      client.release();
    }
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  Patch,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser } from '../../../common/decorators/current-user.decorator';
import { Roles } from '../../../common/decorators/roles.decorator';
import { JwtAuthGuard } from '../../../common/guards/jwt-auth.guard';
import { RolesGuard } from '../../../common/guards/roles.guard';
import { Role } from '../../../shared/enums/role.enum';
import { CreateContractDto } from './dto/create-contract.dto';
import { ContractsService } from '../application/contracts.service';
import { ContractStatus } from '../domain/contract.entity';

import {
  ApiBearerAuth,
  ApiOperation,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';

@ApiTags('Contracts')
@ApiBearerAuth()
@Controller('contracts')
@UseGuards(JwtAuthGuard, RolesGuard)
export class ContractsController {
  constructor(private readonly contractsService: ContractsService) {}

  @ApiOperation({ summary: 'Create a new contract' })
  @ApiResponse({
    status: 201,
    description: 'The contract has been successfully created.',
  })
  @Post()
  @Roles(Role.ADMIN, Role.MANAGER)
  async create(
    @Body() createContractDto: CreateContractDto,
    @CurrentUser() user: any,
  ) {
    return this.contractsService.create(createContractDto, user.userId);
  }

  @ApiOperation({ summary: 'Get all contracts' })
  @ApiResponse({ status: 200, description: 'Return all contracts.' })
  @Get()
  @Roles(Role.ADMIN, Role.MANAGER)
  async findAll(
    @Query('clientId') clientId?: string,
    @Query('status') status?: ContractStatus,
  ) {
    return this.contractsService.findAll({ clientId, status });
  }

  @ApiOperation({ summary: 'Get contract by ID' })
  @ApiResponse({ status: 200, description: 'Return contract by ID.' })
  @ApiResponse({ status: 404, description: 'Contract not found.' })
  @Get(':id')
  @Roles(Role.ADMIN, Role.MANAGER)
  async findById(@Param('id') id: string) {
    return this.contractsService.findById(id);
  }

  @ApiOperation({ summary: 'Approve contract' })
  @ApiResponse({ status: 200, description: 'Contract approved successfully.' })
  @Patch(':id/approve')
  @Roles(Role.ADMIN, Role.MANAGER)
  async approve(@Param('id') id: string) {
    return this.contractsService.approve(id);
  }

  @ApiOperation({ summary: 'Sign contract' })
  @ApiResponse({ status: 200, description: 'Contract signed successfully.' })
  @Patch(':id/sign')
  @Roles(Role.ADMIN, Role.MANAGER)
  async sign(@Param('id') id: string, @Body('signedUrl') signedUrl: string) {
    return this.contractsService.sign(id, signedUrl);
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { BadRequestException, NotFoundException } from '@nestjs/common';
import { ContractsService } from './contracts.service';
import { ContractsRepository } from '../infrastructure/contracts.repository';
import { ContractStatus } from '../domain/contract.entity';

describe('ContractsService', () => {
  let service: ContractsService;
  let contractsRepo: Partial<jest.Mocked<ContractsRepository>>;

  const mockContract: any = {
    id: 'contract-1',
    clientId: 'client-1',
    title: 'SEO Agreement',
    description: 'SEO services for 12 months',
    status: ContractStatus.DRAFT,
    startDate: new Date('2026-01-01'),
    endDate: new Date('2026-12-31'),
    value: 10000,
    createdBy: 'user-1',
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  const mockCreateDto: any = {
    clientId: 'client-1',
    title: 'SEO Agreement',
    description: 'SEO services for 12 months',
    startDate: '2026-01-01',
    endDate: '2026-12-31',
    value: 10000,
  };

  beforeEach(async () => {
    contractsRepo = {
      create: jest.fn(),
      findById: jest.fn(),
      findAll: jest.fn(),
      updateStatus: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ContractsService,
        { provide: ContractsRepository, useValue: contractsRepo },
      ],
    }).compile();

    service = module.get<ContractsService>(ContractsService);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('create', () => {
    it('should create contract with DRAFT status by default', async () => {
      contractsRepo.create.mockResolvedValue(mockContract);

      const result = await service.create(mockCreateDto, 'user-1');

      expect(result).toEqual(mockContract);
      expect(contractsRepo.create).toHaveBeenCalledWith(
        expect.objectContaining({
          clientId: 'client-1',
          title: 'SEO Agreement',
          status: ContractStatus.DRAFT,
          createdBy: 'user-1',
        }),
      );
    });

    it('should throw BadRequestException when endDate is before startDate', async () => {
      const invalidDto: any = {
        ...mockCreateDto,
        startDate: '2026-12-31',
        endDate: '2026-01-01', // before start
      };

      await expect(service.create(invalidDto, 'user-1')).rejects.toThrow(
        BadRequestException,
      );

      expect(contractsRepo.create).not.toHaveBeenCalled();
    });

    it('should create contract without endDate', async () => {
      const dtoNoEnd: any = { ...mockCreateDto, endDate: undefined };
      contractsRepo.create.mockResolvedValue({
        ...mockContract,
        endDate: undefined,
      });

      const result = await service.create(dtoNoEnd, 'user-1');

      expect(result).toBeDefined();
      expect(contractsRepo.create).toHaveBeenCalled();
    });
  });

  describe('findById', () => {
    it('should return contract if found', async () => {
      contractsRepo.findById.mockResolvedValue(mockContract);

      const result = await service.findById('contract-1');

      expect(result).toEqual(mockContract);
    });

    it('should throw NotFoundException if not found', async () => {
      contractsRepo.findById.mockResolvedValue(null);

      await expect(service.findById('non-existent')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('findAll', () => {
    it('should delegate to repository with filters', async () => {
      contractsRepo.findAll.mockResolvedValue([mockContract]);

      const result = await service.findAll({
        clientId: 'client-1',
        status: ContractStatus.DRAFT,
      });

      expect(result).toHaveLength(1);
      expect(contractsRepo.findAll).toHaveBeenCalledWith({
        clientId: 'client-1',
        status: ContractStatus.DRAFT,
      });
    });
  });

  describe('approve', () => {
    it('should approve a DRAFT contract', async () => {
      contractsRepo.findById.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.DRAFT,
      });
      contractsRepo.updateStatus.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.APPROVED,
      });

      const result = await service.approve('contract-1');

      expect(result?.status).toBe(ContractStatus.APPROVED);
      expect(contractsRepo.updateStatus).toHaveBeenCalledWith(
        'contract-1',
        ContractStatus.APPROVED,
      );
    });

    it('should approve a PENDING_APPROVAL contract', async () => {
      contractsRepo.findById.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.PENDING_APPROVAL,
      });
      contractsRepo.updateStatus.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.APPROVED,
      });

      await service.approve('contract-1');

      expect(contractsRepo.updateStatus).toHaveBeenCalledWith(
        'contract-1',
        ContractStatus.APPROVED,
      );
    });

    it('should throw BadRequestException when contract is already SIGNED', async () => {
      contractsRepo.findById.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.SIGNED,
      });

      await expect(service.approve('contract-1')).rejects.toThrow(
        BadRequestException,
      );

      expect(contractsRepo.updateStatus).not.toHaveBeenCalled();
    });

    it('should throw NotFoundException when contract not found', async () => {
      contractsRepo.findById.mockResolvedValue(null);

      await expect(service.approve('non-existent')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('sign', () => {
    it('should sign an APPROVED contract', async () => {
      contractsRepo.findById.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.APPROVED,
      });
      contractsRepo.updateStatus.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.SIGNED,
        signedUrl: 'https://example.com/signed.pdf',
      });

      const result = await service.sign(
        'contract-1',
        'https://example.com/signed.pdf',
      );

      expect(result?.status).toBe(ContractStatus.SIGNED);
      expect(contractsRepo.updateStatus).toHaveBeenCalledWith(
        'contract-1',
        ContractStatus.SIGNED,
        'https://example.com/signed.pdf',
      );
    });

    it('should throw BadRequestException when contract is not APPROVED', async () => {
      contractsRepo.findById.mockResolvedValue({
        ...mockContract,
        status: ContractStatus.DRAFT,
      });

      await expect(
        service.sign('contract-1', 'https://example.com/signed.pdf'),
      ).rejects.toThrow(BadRequestException);

      expect(contractsRepo.updateStatus).not.toHaveBeenCalled();
    });
  });
});

export enum ContractStatus {
  DRAFT = 'DRAFT',
  PENDING_APPROVAL = 'PENDING_APPROVAL',
  APPROVED = 'APPROVED',
  SIGNED = 'SIGNED',
  EXPIRED = 'EXPIRED',
  TERMINATED = 'TERMINATED',
}

export interface ContractEntity {
  id: string;
  clientId: string;
  title: string;
  description?: string;
  status: ContractStatus;
  startDate: Date;
  endDate?: Date;
  value?: number;
  signedUrl?: string;
  createdBy?: string;
  createdAt: Date;
  updatedAt: Date;
}

export class Contract implements ContractEntity {
  id: string;
  clientId: string;
  title: string;
  description?: string;
  status: ContractStatus;
  startDate: Date;
  endDate?: Date;
  value?: number;
  signedUrl?: string;
  createdBy?: string;
  createdAt: Date;
  updatedAt: Date;

  static fromRow(row: any): Contract {
    const entity = new Contract();
    entity.id = row.id;
    entity.clientId = row.client_id;
    entity.title = row.title;
    entity.description = row.description;
    entity.status = row.status;
    entity.startDate = row.start_date;
    entity.endDate = row.end_date;
    entity.value = row.value ? parseFloat(row.value) : undefined;
    entity.signedUrl = row.signed_url;
    entity.createdBy = row.created_by;
    entity.createdAt = row.created_at;
    entity.updatedAt = row.updated_at;
    return entity;
  }
}

