import { Injectable } from '@nestjs/common';
import { PoolClient } from 'pg';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import {
  Contract,
  ContractEntity,
  ContractStatus,
} from '../domain/contract.entity';

@Injectable()
export class ContractsRepository {
  constructor(private readonly db: DatabasePool) {}

  async create(
    contract: ContractEntity,
    client?: PoolClient,
  ): Promise<ContractEntity> {
    const sql = `
            INSERT INTO contracts (
                client_id, title, description, status, start_date, end_date, value, created_by
            )
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
            RETURNING *;
        `;
    const params = [
      contract.clientId,
      contract.title,
      contract.description,
      contract.status,
      contract.startDate,
      contract.endDate,
      contract.value,
      contract.createdBy,
    ];
    const dbClient = client || (await this.db.getPool().connect());
    const shouldRelease = !client;
    try {
      const row = await BaseQuery.queryOne<any>(dbClient, sql, params);
      return Contract.fromRow(row);
    } finally {
      if (shouldRelease) dbClient.release();
    }
  }

  async findById(id: string): Promise<ContractEntity | null> {
    const sql = `SELECT * FROM contracts WHERE id = $1`;
    const client = await this.db.getPool().connect();
    try {
      const row = await BaseQuery.queryOne<any>(client, sql, [id]);
      return row ? Contract.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findAll(filters: {
    clientId?: string;
    status?: ContractStatus;
  }): Promise<ContractEntity[]> {
    let sql = `SELECT * FROM contracts WHERE 1=1`;
    const params: any[] = [];

    if (filters.clientId) {
      params.push(filters.clientId);
      sql += ` AND client_id = $${params.length}`;
    }
    if (filters.status) {
      params.push(filters.status);
      sql += ` AND status = $${params.length}`;
    }

    sql += ` ORDER BY created_at DESC`;

    const client = await this.db.getPool().connect();
    try {
      const rows = await BaseQuery.queryMany<any>(client, sql, params);
      return rows.map((row) => Contract.fromRow(row));
    } finally {
      client.release();
    }
  }

  async updateStatus(
    id: string,
    status: ContractStatus,
    signedUrl?: string,
  ): Promise<ContractEntity | null> {
    let sql = `UPDATE contracts SET status = $2`;
    const params: any[] = [id, status];

    if (signedUrl) {
      params.push(signedUrl);
      sql += `, signed_url = $${params.length}`;
    }

    sql += `, updated_at = NOW() WHERE id = $1 RETURNING *`;

    const client = await this.db.getPool().connect();
    try {
      const row = await BaseQuery.queryOne<any>(client, sql, params);
      return row ? Contract.fromRow(row) : null;
    } finally {
      client.release();
    }
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  Post,
  Res,
  UploadedFile,
  UseGuards,
  UseInterceptors,
  NotFoundException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { Response } from 'express';
import { CurrentUser } from '../../../common/decorators/current-user.decorator';
import { JwtAuthGuard } from '../../../common/guards/jwt-auth.guard';
import { UploadFileUseCase } from '../application/usecases/upload-file.usecase';
import { GetFileUseCase } from '../application/usecases/get-file.usecase';
import { FileUploadMetadataDto } from './dto/file-upload.dto';
import {
  ApiBearerAuth,
  ApiBody,
  ApiConsumes,
  ApiOperation,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';

@ApiTags('Files')
@ApiBearerAuth()
@Controller('files')
@UseGuards(JwtAuthGuard)
export class FilesController {
  constructor(
    private readonly uploadFileUseCase: UploadFileUseCase,
    private readonly getFileUseCase: GetFileUseCase,
  ) {}

  @ApiOperation({ summary: 'Upload a file' })
  @ApiResponse({ status: 201, description: 'File uploaded successfully.' })
  @ApiConsumes('multipart/form-data')
  @ApiBody({
    schema: {
      type: 'object',
      properties: {
        file: {
          type: 'string',
          format: 'binary',
        },
        entityType: { type: 'string' },
        entityId: { type: 'string' },
        folderPath: { type: 'string' },
        isPublic: { type: 'boolean' },
      },
    },
  })
  @Post('upload')
  @UseInterceptors(FileInterceptor('file'))
  async uploadFile(
    @UploadedFile() file: Express.Multer.File,
    @Body() metadata: FileUploadMetadataDto,
    @CurrentUser() user: any,
  ) {
    if (!file) {
      throw new Error('File is required');
    }
    return this.uploadFileUseCase.execute(file, metadata, user.userId);
  }

  @ApiOperation({ summary: 'Download a file' })
  @ApiResponse({ status: 200, description: 'File stream.' })
  @Get(':id/download')
  async downloadFile(@Param('id') id: string, @Res() res: Response) {
    const file = await this.getFileUseCase.execute(id);

    if (!file || !file.filePath) {
      throw new NotFoundException('File not found');
    }

    // Redirect to static URL
    res.redirect(file.filePath);
  }

  @ApiOperation({ summary: 'Get file metadata' })
  @ApiResponse({ status: 200, description: 'Return file metadata.' })
  @ApiResponse({ status: 404, description: 'File not found.' })
  @Get(':id')
  async getMetadata(@Param('id') id: string) {
    return this.getFileUseCase.execute(id);
  }
}

