import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { Notification } from '../domain/notification.entity';
import { NotificationQueryDto } from '../api/dto/notification-query.dto';
import { NotificationsSql } from './sql/notifications.sql';

@Injectable()
export class NotificationsRepository {
  constructor(private readonly dbPool: DatabasePool) {}

  async create(data: {
    userId: string;
    type: string;
    title: string;
    message: string;
    metadata?: Record<string, any>;
  }): Promise<Notification> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(client, NotificationsSql.create, [
        data.userId,
        data.type,
        data.title,
        data.message,
        data.metadata || {},
      ]);
      return new Notification(this.mapRow(row));
    } finally {
      client.release();
    }
  }

  async findByUser(
    userId: string,
    query: NotificationQueryDto,
  ): Promise<Notification[]> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = [`user_id = $1`];
      const params: any[] = [userId];
      let idx = 2;

      if (query.isRead !== undefined) {
        conditions.push(`is_read = $${idx++}`);
        params.push(query.isRead);
      }
      if (query.type) {
        conditions.push(`type = $${idx++}`);
        params.push(query.type);
      }

      const where = `WHERE ${conditions.join(' AND ')}`;

      const rows = await BaseQuery.queryMany(
        client,
        `${NotificationsSql.findByUserBase}
                 ${where}
                 ORDER BY created_at DESC
                 LIMIT 50`,
        params,
      );
      return rows.map((row) => new Notification(this.mapRow(row)));
    } finally {
      client.release();
    }
  }

  async markAsRead(id: string): Promise<boolean> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const count = await BaseQuery.execute(
        client,
        NotificationsSql.markAsRead,
        [id],
      );
      return count > 0;
    } finally {
      client.release();
    }
  }

  async markAllAsRead(userId: string): Promise<void> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      await BaseQuery.execute(client, NotificationsSql.markAllAsRead, [userId]);
    } finally {
      client.release();
    }
  }

  async countUnread(userId: string): Promise<number> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne<{ count: string }>(
        client,
        NotificationsSql.countUnread,
        [userId],
      );
      return parseInt(row?.count || '0', 10);
    } finally {
      client.release();
    }
  }

  private mapRow(row: any): Partial<Notification> {
    return {
      id: row.id,
      userId: row.user_id,
      type: row.type,
      title: row.title,
      message: row.message,
      isRead: row.is_read,
      metadata: row.metadata,
      createdAt: row.created_at,
    };
  }
}

import {
  OnGatewayConnection,
  OnGatewayDisconnect,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';

@WebSocketGateway({
  namespace: 'notifications',
  cors: {
    origin: '*', // Adjust in production
  },
})
export class NotificationsGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(NotificationsGateway.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async handleConnection(client: Socket) {
    try {
      const token = this.extractToken(client);
      if (!token) {
        this.logger.warn(`Client ${client.id} has no token`);
        client.disconnect();
        return;
      }

      const payload = this.jwtService.verify(token, {
        secret: this.configService.get('jwt.secret'),
      });

      const userId = payload.sub;
      client.join(userId); // Join room named by userId
      this.logger.log(`Client ${client.id} connected as User ${userId}`);
    } catch (err) {
      this.logger.error(
        `Connection error for client ${client.id}: ${err.message}`,
      );
      client.disconnect();
    }
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client ${client.id} disconnected`);
  }

  notifyUser(userId: string, payload: any) {
    this.server.to(userId).emit('notification', payload);
  }

  private extractToken(client: Socket): string | undefined {
    const authHeader = client.handshake.headers.authorization;
    if (authHeader && authHeader.split(' ')[0] === 'Bearer') {
      return authHeader.split(' ')[1];
    }
    const queryToken = client.handshake.query.token;
    if (typeof queryToken === 'string') {
      return queryToken;
    }
    return undefined;
  }
}

