import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { Ticket, TicketEntity } from '../domain/ticket.entity';

@Injectable()
export class TicketsRepository {
  constructor(private readonly dbPool: DatabasePool) {}

  async create(data: {
    subject: string;
    description: string;
    type: string;
    priority: string;
    createdBy: string;
  }): Promise<TicketEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `INSERT INTO tickets (subject, description, type, priority, created_by)
                 VALUES ($1, $2, $3, $4, $5)
                 RETURNING *`,
        [
          data.subject,
          data.description,
          data.type,
          data.priority,
          data.createdBy,
        ],
      );
      return Ticket.fromRow(row);
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<TicketEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `SELECT t.*,
                        c.email as creator_email, c.first_name as creator_first_name, c.last_name as creator_last_name,
                        a.email as assignee_email, a.first_name as assignee_first_name, a.last_name as assignee_last_name
                 FROM tickets t
                 JOIN users c ON c.id = t.created_by
                 LEFT JOIN users a ON a.id = t.assigned_to
                 WHERE t.id = $1`,
        [id],
      );
      return row ? Ticket.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findAll(
    filters: {
      page?: number;
      limit?: number;
      status?: string;
      priority?: string;
      type?: string;
    },
    userId?: string, // If provided, filter by creator or assignee
  ): Promise<{ data: TicketEntity[]; total: number }> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = [];
      const params: any[] = [];
      let idx = 1;

      if (filters.status) {
        conditions.push(`t.status = $${idx++}`);
        params.push(filters.status);
      }
      if (filters.priority) {
        conditions.push(`t.priority = $${idx++}`);
        params.push(filters.priority);
      }
      if (filters.type) {
        conditions.push(`t.type = $${idx++}`);
        params.push(filters.type);
      }

      // Access control: If userId provided (non-admin), show created OR assigned tickets
      if (userId) {
        conditions.push(`(t.created_by = $${idx} OR t.assigned_to = $${idx})`);
        params.push(userId);
        idx++;
      }

      const where = conditions.length
        ? `WHERE ${conditions.join(' AND ')}`
        : '';
      const page = filters.page || 1;
      const limit = filters.limit || 20;

      const countResult = await BaseQuery.queryOne<{ count: string }>(
        client,
        `SELECT COUNT(*) as count FROM tickets t ${where}`,
        params,
      );
      const total = parseInt(countResult?.count || '0', 10);

      const offset = (page - 1) * limit;
      params.push(limit, offset);
      const rows = await BaseQuery.queryMany(
        client,
        `SELECT t.*,
                        c.email as creator_email, c.first_name as creator_first_name, c.last_name as creator_last_name,
                        a.email as assignee_email, a.first_name as assignee_first_name, a.last_name as assignee_last_name
                 FROM tickets t
                 JOIN users c ON c.id = t.created_by
                 LEFT JOIN users a ON a.id = t.assigned_to
                 ${where}
                 ORDER BY t.created_at DESC
                 LIMIT $${idx++} OFFSET $${idx++}`,
        params,
      );
      return { data: rows.map(Ticket.fromRow), total };
    } finally {
      client.release();
    }
  }

  async updateStatus(id: string, status: string): Promise<TicketEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `UPDATE tickets SET status = $1, updated_at = NOW() WHERE id = $2 RETURNING *`,
        [status, id],
      );
      return row ? Ticket.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async assign(id: string, assigneeId: string): Promise<TicketEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `UPDATE tickets SET assigned_to = $1, updated_at = NOW() WHERE id = $2 RETURNING *`,
        [assigneeId, id],
      );
      return row ? Ticket.fromRow(row) : null;
    } finally {
      client.release();
    }
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { TimeTrackingService } from '../application/time-tracking.service';
import { StartTimeEntryDto } from './dto/start-time-entry.dto';
import { CreateTimeEntryDto } from './dto/create-time-entry.dto';
import { TimeEntryQueryDto } from './dto/time-entry-query.dto';
import { JwtAuthGuard } from '../../../common/guards/jwt-auth.guard';
import { RolesGuard } from '../../../common/guards/roles.guard';
import { Roles } from '../../../common/decorators/roles.decorator';
import { CurrentUser } from '../../../common/decorators/current-user.decorator';

@Controller('time-entries')
@UseGuards(JwtAuthGuard)
export class TimeTrackingController {
  constructor(private readonly timeService: TimeTrackingService) {}

  @Post('start')
  async startTimer(@Body() dto: StartTimeEntryDto, @CurrentUser() user: any) {
    return this.timeService.startTimer(user.userId, dto);
  }

  @Patch('stop')
  async stopTimer(@CurrentUser() user: any) {
    return this.timeService.stopTimer(user.userId);
  }

  @Get('active')
  async getActiveTimer(@CurrentUser() user: any) {
    return this.timeService.getActiveTimer(user.userId);
  }

  @Post()
  async createManual(
    @Body() dto: CreateTimeEntryDto,
    @CurrentUser() user: any,
  ) {
    return this.timeService.createManualEntry(user.userId, dto);
  }

  @Get()
  async findAll(@Query() query: TimeEntryQueryDto, @CurrentUser() user: any) {
    return this.timeService.findAll(query, user.userId, user.role);
  }

  @Patch(':id/approve')
  @UseGuards(RolesGuard)
  @Roles('ADMIN', 'MANAGER')
  async approve(@Param('id', ParseUUIDPipe) id: string) {
    return this.timeService.approve(id);
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { TimeTrackingService } from './time-tracking.service';
import { TimeEntriesRepository } from '../infrastructure/time-entries.repository';
import {
  ActiveTimerExistsException,
  NoActiveTimerException,
  TimeEntryNotFoundException,
  TimeEntryAlreadyApprovedException,
} from '../domain/time-tracking.errors';

describe('TimeTrackingService', () => {
  let service: TimeTrackingService;
  let timeRepo: Partial<jest.Mocked<TimeEntriesRepository>>;

  const mockEntry: any = {
    id: 'entry-1',
    userId: 'user-1',
    projectId: 'proj-1',
    taskId: 'task-1',
    startTime: new Date(),
    endTime: null,
    durationMinutes: null,
    description: 'Working on feature',
    isManual: false,
    approved: false,
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  beforeEach(async () => {
    timeRepo = {
      findActiveTimer: jest.fn(),
      start: jest.fn(),
      stop: jest.fn(),
      createManual: jest.fn(),
      findById: jest.fn(),
      findAll: jest.fn(),
      approve: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        TimeTrackingService,
        { provide: TimeEntriesRepository, useValue: timeRepo },
      ],
    }).compile();

    service = module.get<TimeTrackingService>(TimeTrackingService);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('startTimer', () => {
    it('should start a new timer when no active timer exists', async () => {
      timeRepo.findActiveTimer.mockResolvedValue(null);
      timeRepo.start.mockResolvedValue(mockEntry);

      const dto: any = {
        projectId: 'proj-1',
        taskId: 'task-1',
        description: 'Working on feature',
      };
      const result = await service.startTimer('user-1', dto);

      expect(result).toEqual(mockEntry);
      expect(timeRepo.start).toHaveBeenCalledWith(
        'user-1',
        'proj-1',
        'task-1',
        'Working on feature',
      );
    });

    it('should throw ActiveTimerExistsException when user already has an active timer', async () => {
      timeRepo.findActiveTimer.mockResolvedValue(mockEntry);

      await expect(service.startTimer('user-1', {} as any)).rejects.toThrow(
        ActiveTimerExistsException,
      );

      expect(timeRepo.start).not.toHaveBeenCalled();
    });
  });

  describe('stopTimer', () => {
    it('should stop the active timer', async () => {
      const stoppedEntry = { ...mockEntry, endTime: new Date() };
      timeRepo.findActiveTimer.mockResolvedValue(mockEntry);
      timeRepo.stop.mockResolvedValue(stoppedEntry);

      const result = await service.stopTimer('user-1');

      expect(result.endTime).toBeDefined();
      expect(timeRepo.stop).toHaveBeenCalledWith('entry-1');
    });

    it('should throw NoActiveTimerException when no active timer', async () => {
      timeRepo.findActiveTimer.mockResolvedValue(null);

      await expect(service.stopTimer('user-1')).rejects.toThrow(
        NoActiveTimerException,
      );

      expect(timeRepo.stop).not.toHaveBeenCalled();
    });
  });

  describe('getActiveTimer', () => {
    it('should return active timer or null', async () => {
      timeRepo.findActiveTimer.mockResolvedValue(mockEntry);

      const result = await service.getActiveTimer('user-1');

      expect(result).toEqual(mockEntry);
    });
  });

  describe('createManualEntry', () => {
    it('should create a manual time entry', async () => {
      const manualEntry = { ...mockEntry, isManual: true };
      timeRepo.createManual.mockResolvedValue(manualEntry);

      const dto: any = {
        projectId: 'proj-1',
        taskId: 'task-1',
        startTime: '2026-01-01T09:00:00Z',
        endTime: '2026-01-01T17:00:00Z',
        description: 'Full day work',
      };

      const result = await service.createManualEntry('user-1', dto);

      expect(result.isManual).toBe(true);
      expect(timeRepo.createManual).toHaveBeenCalledWith(
        expect.objectContaining({
          userId: 'user-1',
          startTime: '2026-01-01T09:00:00Z',
          endTime: '2026-01-01T17:00:00Z',
        }),
      );
    });
  });

  describe('findAll', () => {
    it('should allow ADMIN to query any user', async () => {
      timeRepo.findAll.mockResolvedValue({ data: [], total: 0 });

      await service.findAll(
        { userId: 'other-user' } as any,
        'current-user',
        'ADMIN',
      );

      expect(timeRepo.findAll).toHaveBeenCalledWith(
        expect.objectContaining({ userId: 'other-user' }),
      );
    });

    it('should allow MANAGER to query any user', async () => {
      timeRepo.findAll.mockResolvedValue({ data: [], total: 0 });

      await service.findAll(
        { userId: 'other-user' } as any,
        'current-user',
        'MANAGER',
      );

      expect(timeRepo.findAll).toHaveBeenCalledWith(
        expect.objectContaining({ userId: 'other-user' }),
      );
    });

    it('should force current userId for non-admin users', async () => {
      timeRepo.findAll.mockResolvedValue({ data: [], total: 0 });

      await service.findAll(
        { userId: 'other-user' } as any,
        'current-user',
        'EMPLOYEE',
      );

      expect(timeRepo.findAll).toHaveBeenCalledWith(
        expect.objectContaining({ userId: 'current-user' }),
      );
    });
  });

  describe('approve', () => {
    it('should approve an unapproved entry', async () => {
      timeRepo.findById.mockResolvedValue({ ...mockEntry, approved: false });
      timeRepo.approve.mockResolvedValue({ ...mockEntry, approved: true });

      const result = await service.approve('entry-1');

      expect(result.approved).toBe(true);
      expect(timeRepo.approve).toHaveBeenCalledWith('entry-1');
    });

    it('should throw TimeEntryNotFoundException if entry not found', async () => {
      timeRepo.findById.mockResolvedValue(null);

      await expect(service.approve('non-existent')).rejects.toThrow(
        TimeEntryNotFoundException,
      );
    });

    it('should throw TimeEntryAlreadyApprovedException if already approved', async () => {
      timeRepo.findById.mockResolvedValue({ ...mockEntry, approved: true });

      await expect(service.approve('entry-1')).rejects.toThrow(
        TimeEntryAlreadyApprovedException,
      );

      expect(timeRepo.approve).not.toHaveBeenCalled();
    });
  });
});

export interface TimeEntryEntity {
  id: string;
  userId: string;
  projectId: string | null;
  taskId: string | null;
  startTime: Date;
  endTime: Date | null;
  durationMinutes: number | null;
  description: string | null;
  isManual: boolean;
  approved: boolean;
  createdAt: Date;
  updatedAt: Date;
  // joined fields
  projectName?: string;
  taskTitle?: string;
  userEmail?: string;
  userFirstName?: string;
  userLastName?: string;
}

export class TimeEntry {
  static fromRow(row: any): TimeEntryEntity {
    return {
      id: row.id,
      userId: row.user_id,
      projectId: row.project_id,
      taskId: row.task_id,
      startTime: row.start_time,
      endTime: row.end_time,
      durationMinutes: row.duration_minutes,
      description: row.description,
      isManual: row.is_manual,
      approved: row.approved,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      projectName: row.project_name,
      taskTitle: row.task_title,
      userEmail: row.user_email,
      userFirstName: row.user_first_name,
      userLastName: row.user_last_name,
    };
  }
}

