import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { TimeEntry, TimeEntryEntity } from '../domain/time-entry.entity';

@Injectable()
export class TimeEntriesRepository {
  constructor(private readonly dbPool: DatabasePool) {}

  async findActiveTimer(userId: string): Promise<TimeEntryEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `SELECT t.*,
                        p.name as project_name,
                        tk.title as task_title,
                        u.email as user_email, u.first_name as user_first_name, u.last_name as user_last_name
                 FROM time_entries t
                 LEFT JOIN projects p ON p.id = t.project_id
                 LEFT JOIN tasks tk ON tk.id = t.task_id
                 JOIN users u ON u.id = t.user_id
                 WHERE t.user_id = $1 AND t.end_time IS NULL`,
        [userId],
      );
      return row ? TimeEntry.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async start(
    userId: string,
    projectId?: string,
    taskId?: string,
    description?: string,
  ): Promise<TimeEntryEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `INSERT INTO time_entries (user_id, project_id, task_id, start_time, description)
                 VALUES ($1, $2, $3, NOW(), $4)
                 RETURNING *`,
        [userId, projectId || null, taskId || null, description || null],
      );
      return TimeEntry.fromRow(row);
    } finally {
      client.release();
    }
  }

  async stop(id: string): Promise<TimeEntryEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `UPDATE time_entries
                 SET end_time = NOW()
                 WHERE id = $1
                 RETURNING *`,
        [id],
      );
      return row ? TimeEntry.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async createManual(data: {
    userId: string;
    projectId?: string;
    taskId?: string;
    startTime: string;
    endTime: string;
    description?: string;
  }): Promise<TimeEntryEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `INSERT INTO time_entries (user_id, project_id, task_id, start_time, end_time, description, is_manual)
                 VALUES ($1, $2, $3, $4, $5, $6, true)
                 RETURNING *`,
        [
          data.userId,
          data.projectId || null,
          data.taskId || null,
          data.startTime,
          data.endTime,
          data.description || null,
        ],
      );
      return TimeEntry.fromRow(row);
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<TimeEntryEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `SELECT * FROM time_entries WHERE id = $1`,
        [id],
      );
      return row ? TimeEntry.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async findAll(filters: {
    page?: number;
    limit?: number;
    startDate?: string;
    endDate?: string;
    projectId?: string;
    userId?: string;
  }): Promise<{ data: TimeEntryEntity[]; total: number }> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = [];
      const params: any[] = [];
      let idx = 1;

      if (filters.userId) {
        conditions.push(`t.user_id = $${idx++}`);
        params.push(filters.userId);
      }
      if (filters.projectId) {
        conditions.push(`t.project_id = $${idx++}`);
        params.push(filters.projectId);
      }
      if (filters.startDate) {
        conditions.push(`t.start_time >= $${idx++}`);
        params.push(filters.startDate);
      }
      if (filters.endDate) {
        conditions.push(`t.end_time <= $${idx++}`);
        params.push(filters.endDate);
      }

      const where = conditions.length
        ? `WHERE ${conditions.join(' AND ')}`
        : '';
      const page = filters.page || 1;
      const limit = filters.limit || 20;

      const countResult = await BaseQuery.queryOne<{ count: string }>(
        client,
        `SELECT COUNT(*) as count FROM time_entries t ${where}`,
        params,
      );
      const total = parseInt(countResult?.count || '0', 10);

      const offset = (page - 1) * limit;
      params.push(limit, offset);
      const rows = await BaseQuery.queryMany(
        client,
        `SELECT t.*,
                        p.name as project_name,
                        tk.title as task_title,
                        u.email as user_email, u.first_name as user_first_name, u.last_name as user_last_name
                 FROM time_entries t
                 LEFT JOIN projects p ON p.id = t.project_id
                 LEFT JOIN tasks tk ON tk.id = t.task_id
                 JOIN users u ON u.id = t.user_id
                 ${where}
                 ORDER BY t.start_time DESC
                 LIMIT $${idx++} OFFSET $${idx++}`,
        params,
      );

      return { data: rows.map(TimeEntry.fromRow), total };
    } finally {
      client.release();
    }
  }

  async approve(id: string): Promise<TimeEntryEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(
        client,
        `UPDATE time_entries SET approved = true WHERE id = $1 RETURNING *`,
        [id],
      );
      return row ? TimeEntry.fromRow(row) : null;
    } finally {
      client.release();
    }
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { UsersService } from '../application/users.service';
import { CreateUserDto } from './dto/create-user.dto';
import { UpdateUserDto } from './dto/update-user.dto';
import { UserQueryDto } from './dto/user-query.dto';
import { JwtAuthGuard } from '../../../common/guards/jwt-auth.guard';
import { RolesGuard } from '../../../common/guards/roles.guard';
import { Roles } from '../../../common/decorators/roles.decorator';
import { CurrentUser } from '../../../common/decorators/current-user.decorator';

import {
  ApiBearerAuth,
  ApiOperation,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';

@ApiTags('Users')
@ApiBearerAuth()
@Controller('users')
@UseGuards(JwtAuthGuard)
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @ApiOperation({ summary: 'Get all users' })
  @ApiResponse({ status: 200, description: 'Return all users.' })
  @Get()
  @UseGuards(RolesGuard)
  @Roles('ADMIN', 'MANAGER')
  async findAll(@Query() query: UserQueryDto) {
    return this.usersService.findAll(query);
  }

  @ApiOperation({ summary: 'Get current user profile' })
  @ApiResponse({ status: 200, description: 'Return current user profile.' })
  @Get('me')
  async getProfile(@CurrentUser() user: any) {
    return this.usersService.findById(user.userId);
  }

  @ApiOperation({ summary: 'Get user by ID' })
  @ApiResponse({ status: 200, description: 'Return user by ID.' })
  @ApiResponse({ status: 404, description: 'User not found.' })
  @Get(':id')
  @UseGuards(RolesGuard)
  @Roles('ADMIN', 'MANAGER')
  async findById(@Param('id', ParseUUIDPipe) id: string) {
    return this.usersService.findById(id);
  }

  @ApiOperation({ summary: 'Create a new user' })
  @ApiResponse({
    status: 201,
    description: 'The user has been successfully created.',
  })
  @ApiResponse({ status: 400, description: 'Bad Request.' })
  @Post()
  @UseGuards(RolesGuard)
  @Roles('ADMIN')
  async create(@Body() dto: CreateUserDto) {
    return this.usersService.create(dto);
  }

  @ApiOperation({ summary: 'Update a user' })
  @ApiResponse({
    status: 200,
    description: 'The user has been successfully updated.',
  })
  @ApiResponse({ status: 404, description: 'User not found.' })
  @Put(':id')
  @UseGuards(RolesGuard)
  @Roles('ADMIN')
  async update(
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: UpdateUserDto,
    @CurrentUser() user: any,
  ) {
    return this.usersService.update(id, dto, user.userId);
  }

  @ApiOperation({ summary: 'Deactivate a user' })
  @ApiResponse({
    status: 200,
    description: 'The user has been successfully deactivated.',
  })
  @Patch(':id/deactivate')
  @UseGuards(RolesGuard)
  @Roles('ADMIN')
  async deactivate(
    @Param('id', ParseUUIDPipe) id: string,
    @CurrentUser() user: any,
  ) {
    return this.usersService.deactivate(id, user.userId);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { UsersRepository } from '../../infrastructure/users.repository';
import { PasswordService } from '../../../auth/application/password.service';
import { UpdateUserDto } from '../../api/dto/update-user.dto';
import { User } from '../../domain/user.entity';
import {
  UserNotFoundException,
  UserAlreadyExistsException,
  CannotChangeOwnRoleException,
} from '../../domain/user.errors';

@Injectable()
export class UpdateUserUseCase {
  private readonly logger = new Logger(UpdateUserUseCase.name);

  constructor(
    private readonly usersRepo: UsersRepository,
    private readonly passwordService: PasswordService,
  ) {}

  async execute(
    id: string,
    dto: UpdateUserDto,
    currentUserId: string,
  ): Promise<User> {
    // 1. Check if user exists
    const user = await this.usersRepo.findById(id);
    if (!user) throw new UserNotFoundException();

    // 2. Self-update rule: cannot change own role
    if (id === currentUserId && dto.role && dto.role !== user.role) {
      throw new CannotChangeOwnRoleException();
    }

    // 3. Check email uniqueness if email is being changed
    if (dto.email && dto.email !== user.email) {
      const existing = await this.usersRepo.findByEmail(dto.email);
      if (existing) throw new UserAlreadyExistsException();
    }

    // 4. Handle password update separately
    if (dto.password) {
      const passwordHash = await this.passwordService.hash(dto.password);
      await this.usersRepo.updatePassword(id, passwordHash);
    }

    // 5. Transform keys and update
    // Repository expects camelCase matching the interface?
    // UsersRepository.update takes Partial<{ email, firstName, ... }>
    const updateData: any = {};
    if (dto.email) updateData.email = dto.email;
    if (dto.firstName) updateData.firstName = dto.firstName;
    if (dto.lastName) updateData.lastName = dto.lastName;
    if (dto.role) updateData.role = dto.role;
    if (dto.department) updateData.department = dto.department;

    const updated = await this.usersRepo.update(id, updateData);

    this.logger.log(`User updated: ${id}`);

    return updated instanceof User ? updated : User.fromRow(updated);
  }
}

import { Injectable } from '@nestjs/common';
import { UsersRepository } from '../infrastructure/users.repository';
import { CreateUserDto } from '../api/dto/create-user.dto';
import { UpdateUserDto } from '../api/dto/update-user.dto';
import { UserQueryDto } from '../api/dto/user-query.dto';
import { User } from '../domain/user.entity';
import { UserNotFoundException } from '../domain/user.errors';
import { CreateUserUseCase } from './usecases/create-user.usecase';
import { UpdateUserUseCase } from './usecases/update-user.usecase';
import { DeactivateUserUseCase } from './usecases/deactivate-user.usecase';

@Injectable()
export class UsersService {
  constructor(
    private readonly usersRepo: UsersRepository,
    private readonly createUserUseCase: CreateUserUseCase,
    private readonly updateUserUseCase: UpdateUserUseCase,
    private readonly deactivateUserUseCase: DeactivateUserUseCase,
  ) {}

  async findAll(query: UserQueryDto) {
    const { data, total } = await this.usersRepo.findAll({
      page: query.page || 1,
      limit: query.limit || 20,
      role: query.role,
      department: query.department,
      isActive: query.isActive,
      search: query.search,
    });

    return {
      data: data.map(User.toSafeResponse),
      meta: {
        total,
        page: query.page || 1,
        limit: query.limit || 20,
        totalPages: Math.ceil(total / (query.limit || 20)),
      },
    };
  }

  async findById(id: string) {
    const user = await this.usersRepo.findById(id);
    if (!user) throw new UserNotFoundException();
    return User.toSafeResponse(user);
  }

  async create(dto: CreateUserDto) {
    const user = await this.createUserUseCase.execute(dto);
    return User.toSafeResponse(user);
  }

  async update(id: string, dto: UpdateUserDto, currentUserId: string) {
    const updatedUser = await this.updateUserUseCase.execute(
      id,
      dto,
      currentUserId,
    );
    return User.toSafeResponse(updatedUser);
  }

  async deactivate(id: string, currentUserId: string) {
    const deactivated = await this.deactivateUserUseCase.execute(
      id,
      currentUserId,
    );
    return User.toSafeResponse(deactivated);
  }
}

import { Role } from '../../../shared/enums/role.enum';
import { Department } from '../../../shared/enums/department.enum';

export interface UserEntity {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  department: string | null;
  isActive: boolean;
  forcePasswordChange: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface UserWithPassword extends UserEntity {
  passwordHash: string;
}

export class User implements UserEntity {
  constructor(
    public id: string,
    public email: string,
    public firstName: string,
    public lastName: string,
    public role: string,
    public department: string | null,
    public isActive: boolean,
    public forcePasswordChange: boolean,
    public createdAt: Date,
    public updatedAt: Date,
  ) {}

  static fromRow(row: any): User {
    return new User(
      row.id,
      row.email,
      row.first_name,
      row.last_name,
      row.role,
      row.department,
      row.is_active,
      row.force_password_change,
      row.created_at,
      row.updated_at,
    );
  }

  static toSafeResponse(user: UserEntity) {
    return {
      id: user.id,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      role: user.role,
      department: user.department,
      isActive: user.isActive,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    };
  }

  // Domain Behaviors
  activate() {
    this.isActive = true;
    this.updatedAt = new Date();
  }

  deactivate() {
    this.isActive = false;
    this.updatedAt = new Date();
  }

  changeRole(newRole: Role) {
    this.role = newRole;
    this.updatedAt = new Date();
  }

  changeDepartment(newDept: Department) {
    this.department = newDept;
    this.updatedAt = new Date();
  }
}

