import { Injectable } from '@nestjs/common';
import { DatabasePool } from '../../../database/pool';
import { BaseQuery } from '../../../database/query/base-query';
import { User, UserEntity } from '../domain/user.entity';
import { UsersSql } from './sql/users.sql';

import { CacheService } from '../../../infrastructure/cache/cache.service';

@Injectable()
export class UsersRepository {
  constructor(
    private readonly dbPool: DatabasePool,
    private readonly cacheService: CacheService,
  ) {}

  async findAll(query: {
    page: number;
    limit: number;
    role?: string;
    department?: string;
    isActive?: string;
    search?: string;
  }): Promise<{ data: UserEntity[]; total: number }> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const conditions: string[] = [];
      const params: any[] = [];
      let paramIndex = 1;

      if (query.role) {
        conditions.push(`role = $${paramIndex++}`);
        params.push(query.role);
      }
      if (query.department) {
        conditions.push(`department = $${paramIndex++}`);
        params.push(query.department);
      }
      if (query.isActive !== undefined) {
        conditions.push(`is_active = $${paramIndex++}`);
        params.push(query.isActive === 'true');
      }
      if (query.search) {
        conditions.push(
          `(LOWER(email) LIKE $${paramIndex} OR LOWER(first_name) LIKE $${paramIndex} OR LOWER(last_name) LIKE $${paramIndex})`,
        );
        params.push(`%${query.search.toLowerCase()}%`);
        paramIndex++;
      }

      const whereClause = conditions.length
        ? `WHERE ${conditions.join(' AND ')}`
        : '';

      // Count query
      const countResult = await BaseQuery.queryOne<{ count: string }>(
        client,
        `${UsersSql.findAllCount} ${whereClause}`,
        params,
      );
      const total = parseInt(countResult?.count || '0', 10);

      // Data query with pagination
      const offset = (query.page - 1) * query.limit;
      params.push(query.limit, offset);
      const rows = await BaseQuery.queryMany(
        client,
        `${UsersSql.findAllData} ${whereClause}
                 ORDER BY created_at DESC
                 LIMIT $${paramIndex++} OFFSET $${paramIndex++}`,
        params,
      );

      return {
        data: rows.map(User.fromRow),
        total,
      };
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<UserEntity | null> {
    return this.cacheService.getOrSet(
      `users:${id}`,
      async () => {
        const pool = this.dbPool.getPool();
        const client = await pool.connect();
        try {
          const row = await BaseQuery.queryOne(client, UsersSql.findById, [id]);
          return row ? User.fromRow(row) : null;
        } finally {
          client.release();
        }
      },
      300,
    ); // 5 minutes TTL
  }

  async findByEmail(email: string): Promise<any | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      return BaseQuery.queryOne(client, UsersSql.findByEmail, [email]);
    } finally {
      client.release();
    }
  }

  async create(data: {
    email: string;
    passwordHash: string;
    firstName: string;
    lastName: string;
    role: string;
    department?: string;
  }): Promise<UserEntity> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(client, UsersSql.create, [
        data.email,
        data.passwordHash,
        data.firstName,
        data.lastName,
        data.role,
        data.department || null,
      ]);
      return User.fromRow(row);
    } finally {
      client.release();
    }
  }

  async update(
    id: string,
    data: Partial<{
      email: string;
      firstName: string;
      lastName: string;
      role: string;
      department: string;
    }>,
  ): Promise<UserEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const setClauses: string[] = [];
      const params: any[] = [];
      let paramIndex = 1;

      if (data.email !== undefined) {
        setClauses.push(`email = $${paramIndex++}`);
        params.push(data.email);
      }
      if (data.firstName !== undefined) {
        setClauses.push(`first_name = $${paramIndex++}`);
        params.push(data.firstName);
      }
      if (data.lastName !== undefined) {
        setClauses.push(`last_name = $${paramIndex++}`);
        params.push(data.lastName);
      }
      if (data.role !== undefined) {
        setClauses.push(`role = $${paramIndex++}`);
        params.push(data.role);
      }
      if (data.department !== undefined) {
        setClauses.push(`department = $${paramIndex++}`);
        params.push(data.department);
      }

      if (setClauses.length === 0) return this.findById(id);

      setClauses.push(`updated_at = NOW()`);
      params.push(id);

      const row = await BaseQuery.queryOne(
        client,
        `${UsersSql.updateBase} ${setClauses.join(', ')}
                 WHERE id = $${paramIndex}
                 ${UsersSql.updateReturning}`,
        params,
      );

      if (row) {
        await this.cacheService.del(`users:${id}`);
      }

      return row ? User.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async deactivate(id: string): Promise<UserEntity | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne(client, UsersSql.deactivate, [id]);

      if (row) {
        await this.cacheService.del(`users:${id}`);
      }

      return row ? User.fromRow(row) : null;
    } finally {
      client.release();
    }
  }

  async updatePassword(id: string, passwordHash: string): Promise<void> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      await BaseQuery.execute(client, UsersSql.updatePassword, [
        passwordHash,
        id,
      ]);
      await this.cacheService.del(`users:${id}`);
    } finally {
      client.release();
    }
  }

  async findPasswordHashById(id: string): Promise<string | null> {
    const pool = this.dbPool.getPool();
    const client = await pool.connect();
    try {
      const row = await BaseQuery.queryOne<{ password_hash: string }>(
        client,
        UsersSql.findPasswordHashById,
        [id],
      );
      return row ? row.password_hash : null;
    } finally {
      client.release();
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios from 'axios';
import {
  IEmailOptions,
  IEmailService,
} from '../interfaces/email-service.interface';

@Injectable()
export class EmailJsProvider implements IEmailService {
  private readonly logger = new Logger(EmailJsProvider.name);
  private readonly apiUrl = 'https://api.emailjs.com/api/v1.0/email/send';

  constructor(private readonly configService: ConfigService) {}

  async sendEmail(options: IEmailOptions): Promise<void> {
    const serviceId = this.configService.get('email.serviceId');
    const templateId =
      options.templateId || this.configService.get('email.templateId');
    const userId = this.configService.get('email.userId'); // Public Key
    const accessToken = this.configService.get('email.accessToken'); // Private Key

    if (!serviceId || !userId || !accessToken) {
      this.logger.warn('EmailJS configuration missing. Email not sent.');
      return;
    }

    // Debug config values (masked)
    this.logger.log(`Service ID: ${serviceId}`);
    this.logger.log(`User ID: ${userId}`);
    this.logger.log(
      `Access Token: ${accessToken ? accessToken.substring(0, 5) + '...' : 'MISSING'}`,
    );

    const data = {
      service_id: serviceId,
      template_id: templateId,
      user_id: userId,
      accessToken: accessToken,
      template_params: {
        to_email: options.to, // Common convention
        to: options.to, // Alternative
        recipient: options.to, // Alternative
        reply_to: options.to, // Often required for replies
        subject: options.subject,
        message: options.text || options.html,
        ...options.variables,
      },
    };

    try {
      await axios.post(this.apiUrl, data, {
        headers: {
          'Content-Type': 'application/json',
          Origin: 'http://localhost', // Workaround: Simulate browser origin
        },
      });
      this.logger.log(`Email sent to ${options.to}`);
    } catch (error) {
      this.logger.error(
        `Failed to send email: ${error.message} - ${JSON.stringify(error.response?.data)}`,
      );
      throw error;
    }
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { IStorageProvider, IUploadResult } from './storage.provider.interface';
import { promises as fsPromises, existsSync, mkdirSync } from 'fs';
import * as path from 'path';
import { v4 as uuidv4 } from 'uuid';

@Injectable()
export class LocalFileProvider implements IStorageProvider, OnModuleInit {
  private readonly logger = new Logger(LocalFileProvider.name);
  private readonly uploadDir = 'uploads';

  constructor() {}

  onModuleInit() {
    this.ensureUploadDir();
  }

  private ensureUploadDir() {
    const fullPath = path.resolve(this.uploadDir);
    this.logger.log(`[DEBUG] Checking upload dir: ${fullPath}`);
    try {
      if (!existsSync(this.uploadDir)) {
        mkdirSync(this.uploadDir, { recursive: true });
        this.logger.log(`Created upload directory: ${this.uploadDir}`);
      }
    } catch (error) {
      this.logger.error(`Failed to create upload directory: ${error.message}`);
      // Don't throw, just log. Tests might fail later but we see why.
    }
  }

  async upload(file: Express.Multer.File): Promise<IUploadResult> {
    // We can double check here asynchronously if needed
    const fullPath = path.resolve(this.uploadDir);

    const ext = path.extname(file.originalname);
    const filename = `${uuidv4()}${ext}`;
    const filePath = path.join(this.uploadDir, filename);

    await fsPromises.writeFile(filePath, file.buffer);

    return {
      key: filename,
      url: `/uploads/${filename}`,
      size: file.size,
      mimeType: file.mimetype,
    };
  }

  async delete(key: string): Promise<void> {
    const filePath = path.join(this.uploadDir, key);
    try {
      await fsPromises.unlink(filePath);
    } catch (error) {
      this.logger.warn(`Failed to delete file ${key}: ${error.message}`);
    }
  }
}

// Since we don't have a generic Repository interface yet, we will create generic mock helpers.

export type MockType<T> = {
  [P in keyof T]?: jest.Mock<{}>;
};

export const repositoryMockFactory = <T = any>(): MockType<T> =>
  ({
    findOne: jest.fn(),
    find: jest.fn(),
    create: jest.fn(),
    save: jest.fn(),
    update: jest.fn(),
    delete: jest.fn(),
    // Add specific methods as needed by the repository being mocked
  }) as unknown as MockType<T>;

export const mockProvider = (provide: any, methods: string[] = []) => {
  const mock: any = {};
  methods.forEach((method) => {
    mock[method] = jest.fn();
  });
  return {
    provide,
    useValue: mock,
  };
};
